CREATE OR REPLACE FUNCTION public.report_sighting(_variant_id uuid, _location_id uuid, _availability sighting_availability, _price_cents integer DEFAULT NULL::integer, _note text DEFAULT NULL::text, _seen_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

declare
  _caller uuid := auth.uid();
  _id uuid;
begin
  if _caller is null then
    raise exception 'Sign in to report a sighting.' using errcode = '42501';
  end if;
  perform public.enforce_rate_limit('report_sighting', 10, interval '1 day');

  if not exists (select 1 from public.product_variants v where v.id = _variant_id and v.active) then
    raise exception 'That variation is not available for sightings.';
  end if;
  if not exists (select 1 from public.locations l where l.id = _location_id and l.active) then
    raise exception 'Choose an active park location.';
  end if;
  if _seen_at > now() + interval '1 hour' then
    raise exception 'A sighting cannot be in the future.';
  end if;
  if _seen_at < now() - interval '30 days' then
    raise exception 'Sightings older than 30 days are not useful during the pilot.';
  end if;
  if _price_cents is not null and (_price_cents <= 0 or _price_cents > 500000) then
    raise exception 'Observed price is out of range.';
  end if;

  insert into public.sightings (variant_id, location_id, reporter_id, seen_at, availability, price_cents, note)
  values (_variant_id, _location_id, _caller, _seen_at, _availability, _price_cents,
          nullif(btrim(coalesce(_note, '')), ''))
  returning id into _id;

  return _id;
end;
END;$function$

CREATE OR REPLACE FUNCTION public.respond_to_sighting(_sighting_id uuid, _kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

declare
  _caller uuid := auth.uid();
  _reporter uuid;
begin
  if _caller is null then
    raise exception 'Sign in to respond to a sighting.' using errcode = '42501';
  end if;
  if _kind not in ('confirm', 'flag') then
    raise exception 'Unsupported response.';
  end if;
  perform public.enforce_rate_limit('respond_to_sighting', 40, interval '1 day');

  select reporter_id into _reporter
  from public.sightings
  where id = _sighting_id and not hidden
  for update;

  if _reporter is null then
    raise exception 'That sighting is no longer available.';
  end if;
  if _reporter = _caller then
    raise exception 'You cannot confirm or flag your own sighting.';
  end if;

  insert into public.sighting_confirmations (sighting_id, user_id, kind)
  values (_sighting_id, _caller, _kind)
  on conflict (sighting_id, user_id) do nothing;

  if not found then
    raise exception 'You have already responded to this sighting.';
  end if;

  update public.sightings s
  set confirmation_count = (select count(*) from public.sighting_confirmations c
                            where c.sighting_id = s.id and c.kind = 'confirm'),
      flag_count = (select count(*) from public.sighting_confirmations c
                    where c.sighting_id = s.id and c.kind = 'flag')
  where s.id = _sighting_id;
end;
END;$function$

rateLimitFunction.definition:
CREATE OR REPLACE FUNCTION public.enforce_rate_limit(_action text, _max integer, _window interval)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE uid uuid := auth.uid(); used integer;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  SELECT count(*) INTO used FROM public.rate_limit_events
   WHERE user_id = uid AND action = _action AND created_at > now() - _window;
  IF used >= _max THEN
    RAISE EXCEPTION 'You have reached the limit for this action. Please try again later.';
  END IF;
  INSERT INTO public.rate_limit_events (user_id, action) VALUES (uid, _action);
END;
END;$function$
